<?php require 'includes/bootstrap.php';$u=login_required();$result=null;$error='';if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$amount=(float)($_POST['amount']??0);$beneficiary=trim($_POST['beneficiary']??'');if($amount<=0||strlen($beneficiary)<2)$error='Enter a valid amount and beneficiary.';else{[$score,$level,$why]=risk($amount);$status=$level==='high'?'held for review':'approved';$s=$pdo->prepare('INSERT INTO transactions(user_id,amount,beneficiary,risk_score,risk_level,risk_reasons,status) VALUES(?,?,?,?,?,?,?)');$s->execute([$u['id'],$amount,$beneficiary,$score,$level,json_encode($why),$status]);audit('transaction_assessed',(int)$u['id'],"score=$score");$result=compact('score','level','why','status');}}$pageTitle='AI risk assessment';require 'includes/header.php';?><section class="grid two"><div class="card"><h1>Assess transaction</h1><?php if($error):?><p class="error"><?=e($error)?></p><?php endif?><form method="post"><input type="hidden" name="csrf" value="<?=csrf()?>"><label>Beneficiary<input name="beneficiary" required></label><label>Amount (GHS)<input type="number" name="amount" min="0.01" step="0.01" required></label><button class="button">Run risk assessment</button></form></div><div class="card"><h2>Explainable result</h2><?php if($result):?><progress max="100" value="<?=e((string)$result['score'])?>"><?=e((string)$result['score'])?>%</progress><h1><?=e((string)$result['score'])?> / 100 — <?=e(strtoupper($result['level']))?></h1><p>Status: <b><?=e($result['status'])?></b></p><ul><?php foreach($result['why'] as $w):?><li><?=e($w)?></li><?php endforeach?></ul><?php else:?><p>Submit a simulated transaction. This prototype does not transfer money.</p><?php endif?></div></section><?php require 'includes/footer.php';?>
